```xUnit Test Cases
// Test Suite for VIRTUA-4.1 and VIRTUA-4.2 requirements

// Tests for concurrent user scaling
[Test]
public void ConcurrentUserScaling_ShouldHandle10000Users()
{
    // Arrange
    var userSimulator = new UserSimulator(10000);

    // Act
    var result = userSimulator.SimulateConcurrentUsers();

    // Assert
    Assert.AreEqual(10000, result.UserCount);
}

[Test]
public void ConcurrentUserScaling_ShouldNotExceed2Seconds()
{
    // Arrange
    var userSimulator = new UserSimulator(10000);

    // Act
    var startTime = DateTime.Now;
    userSimulator.SimulateConcurrentUsers();
    var endTime = DateTime.Now;

    // Assert
    Assert.IsTrue((endTime - startTime).TotalSeconds <= 2);
}

// Tests for response time during peak period
[Test]
public void ResponseTime_ShouldBeLessThan4SecondsDuringPeakPeriod()
{
    // Arrange
    var userSimulator = new UserSimulator(10000);
    var peakPeriod = new PeakPeriod();

    // Act
    var startTime = DateTime.Now;
    userSimulator.SimulateUsersDuringPeakPeriod(peakPeriod);
    var endTime = DateTime.Now;

    // Assert
    Assert.IsTrue((endTime - startTime).TotalSeconds <= 4);
}

// Tests for system availability
[Test]
public void SystemAvailability_ShouldBe99_999Percent()
{
    // Arrange
    var systemMonitor = new SystemMonitor();

    // Act
    var result = systemMonitor.CheckAvailability();

    // Assert
    Assert.AreEqual(99.999, result.AvailabilityPercentage);
}

// Tests for system outage
[Test]
public void SystemOutage_ShouldOccurOnEvery4thSundayNight()
{
    // Arrange
    var systemMonitor = new SystemMonitor();
    var date = DateTime.Now;

    // Act
    var result = systemMonitor.CheckOutage(date);

    // Assert
    Assert.IsTrue(result.IsOutage && date.DayOfWeek == DayOfWeek.Sunday && date.Hour >= 0 && date.Hour < 10);
}

// Tests for patient registration
[Test]
public void PatientRegistration_ShouldAllowRegistration()
{
    // Arrange
    var registrationSystem = new RegistrationSystem();
    var patient = new Patient();

    // Act
    registrationSystem.RegisterPatient(patient);

    // Assert
    Assert.IsTrue(patient.IsRegistered);
}

// Tests for adding specialties
[Test]
public void AddingSpecialties_ShouldAllowAdminToAddSpecialties()
{
    // Arrange
    var adminSystem = new AdminSystem();
    var specialty = new Specialty();

    // Act
    adminSystem.AddSpecialty(specialty);

    // Assert
    Assert.IsTrue(specialty.IsAdded);
}

// Tests for registering doctors
[Test]
public void RegisteringDoctors_ShouldAllowAdminToRegisterDoctors()
{
    // Arrange
    var adminSystem = new AdminSystem();
    var doctor = new Doctor();

    // Act
    adminSystem.RegisterDoctor(doctor);

    // Assert
    Assert.IsTrue(doctor.IsRegistered);
}
